<template>
    <div id="my-account">
        <section class="hero is-info">
            <div class="hero-body">
                <div class="container">
                    <p class="title">My Account</p>
                    <p class="subtitle">Thunderstore account information</p>
                </div>
            </div>
            <Button class="cta" :onClick="() => router.back()">
                <font-awesome-icon icon="fa-regular fa-xmark-large" fixedWidth size="xs" />
                Close
            </Button>
        </section>

        <div class="container-container">
            <div class="container">
                <div class="panel-block container-breakout">
                    <p class="title is-6">Username</p>
                    <p class="subtitle is-6">{{ username }}</p>
                </div>

                <div class="panel-block row container-breakout">
                    <div class="panel-column">
                        <p class="title is-6">Subscription status</p>
                        <p v-if="owSubscriptionInfo" class="subtitle is-6">
                            {{ owSubscriptionInfo }}
                        </p>
                        <p v-if="tsSubscriptionInfo" class="subtitle is-6">
                            {{ tsSubscriptionInfo }}
                        </p>
                        <p v-if="!owSubscriptionInfo && !tsSubscriptionInfo" class="subtitle is-6">
                            No active subscriptions
                        </p>
                    </div>

                    <div class="panel-column">
                        <Button v-if="false" class="ghost" :onClick="manageSub">
                            Manage subscription
                            <font-awesome-icon icon="fa-regular fa-arrow-up-right-from-square" fixedWidth />
                        </Button>
                    </div>
                </div>

                <div class="panel-block row container-breakout">
                    <div class="panel-column">
                        <p class="title is-6">Hide sensitive information (streamer mode)</p>
                        <p class="subtitle is-6">{{ streamerMode ? "On" : "Off"}}</p>
                    </div>

                    <div class="panel-column centered">
                        <div class="field">
                            <input
                                id="streamer-mode"
                                type="checkbox"
                                class="switch is-small is-info"
                                :checked="streamerMode"
                                @change="toggleStreamerMode"
                            >
                            <label for="streamer-mode" />
                        </div>
                    </div>
                </div>

                <div v-if="false" class="panel-block container-breakout">
                    <Button class="cta" :onClick="manageAccount">
                        Manage account
                        <font-awesome-icon icon="fa-regular fa-arrow-up-right-from-square" fixedWidth />
                    </Button>
                </div>

                <div class="panel-block container-breakout">
                    <Button class="danger ghost" :onClick="logout">
                        Log out
                    </Button>
                </div>
            </div>
        </div>
    </div>
</template>

<script lang="ts" setup>
import Button from '@/overwolf/components/TsButton.vue';
import {openLink} from '@/overwolf/utils/global';
import {computed} from "vue";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/overwolf/store";
import {useRouter} from "vue-router";

const store = getStore<State>();
const router = useRouter();

const streamerMode = computed(() => store.state.userSettings.isStreamerMode);

const owSubscriptionInfo = computed(() => {
    const plan: overwolf.profile.Plan|undefined = store.state.subscription.plan;

    if (plan === undefined) {
        return "";
    }

    const expires = new Date(plan.expiryDate);
    const prefix = "Subscribed via Overwolf - Ends on";
    const endDate = streamerMode.value ? "**/**/****" : expires.toLocaleDateString();
    const suffix = plan.state === "active" ? "(renews automatically)" : "";
    return `${prefix} ${endDate} ${suffix}`;
});

const tsSubscriptionInfo = computed(() => {
    const expires: Date | null = store.getters["auth/subscriptionExpires"];

    if (expires === null) {
        return "";
    }

    return streamerMode.value
        ? "Subscribed via Thunderstore - Ends on **/**/****"
        : `Subscribed via Thunderstore - Ends on ${expires.toLocaleDateString()}`;
});

const username = computed(() => store.getters["shownUsername"]);

async function logout() {
    await store.dispatch("auth/logout");
    await router.push({name: "index"});
}

async function manageAccount() {
    // TODO: point to correct URL once it's available.
    await openLink("https://thunderstore.io");
}

async function manageSub() {
    // TODO: point to correct URL once it's available.
    await openLink("https://thunderstore.io");
}

async function toggleStreamerMode() {
    await store.dispatch("userSettings/toggleStreamerMode");
}
</script>

<style lang="scss" scoped>
.hero button {
    position: absolute;
    top: 0.75rem;
    right: 1rem;
    width: 100px;
}

.panel-block {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
    padding: 1rem;

    &.row {
        flex-direction: row;
    }

    p.title,
    p.subtitle {
        margin: 0;
        line-height: 1;
    }
}

.panel-column {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;

    &.centered {
        align-self: center;
    }

    &:last-of-type {
        margin-left: auto;
        display: flex;
        justify-content: flex-end;
    }
}
</style>
